stomImagePath\"\n                                :alt=\"currentOffer.item | itemName\"\n                                :title=\"currentOffer.item | itemName\">\n                    </lazy-img>\n                </a>\n            </template>\n\n            <template #item-details v-if=\"!!currentOffer && whenIsCurrentOffer() !== 1 && isActiveByStock\">\n                <live-shopping-details :live-shopping-data=\"currentOffer\"\n                                       @reload-offer=\"reloadOffer()\"\n                                       :display-settings=\"displaySettings\"\n                                       :prices=\"prices\"\n                                       :is-active-by-stock=\"isActiveByStock\"\n                                       :show-net-prices=\"showNetPrices\">\n                    <template #after-item-name>\n                        <div class=\"live-shopping-add-to-basket\">\n                            <add-to-basket\n                                    :variation-id=\"currentOffer.item.variation.id\"\n                                    :is-salable=\"!!currentOffer.item.filter && currentOffer.item.filter.isSalable\"\n                                    :has-children=\"!!currentOffer.item.filter && currentOffer.item.filter.hasActiveChildren\"\n                                    :interval-quantity=\"currentOffer.item.variation.intervalOrderQuantity || 1\"\n                                    :minimum-quantity=\"currentOffer.item.variation.minimumOrderQuantity\"\n                                    :maximum-quantity=\"!!currentOffer.item.variation.maximumOrderQuantity && currentOffer.item.variation.maximumOrderQuantity > 0 ? currentOffer.item.variation.maximumOrderQuantity : null\"\n                                    :order-properties=\"currentOffer.item.properties.filter(function(prop) { return prop.property.isOderProperty })\"\n                                    :has-order-properties=\"currentOffer.item.hasOrderProperties\"\n                                    :has-required-order-property=\"currentOffer.hasRequiredOrderProperty\"\n                                    :use-large-scale=\"false\"\n                                    :show-quantity=\"false\"\n                                    :item-url=\"currentOffer.item | itemURL\"\n                                    :item-type=\"currentOffer.item.item.itemType\">\n                            </add-to-basket>\n                        </div>\n                    </template>\n                </live-shopping-details>\n            </template>\n        </category-item>\n        <div v-else>\n            <slot></slot>\n        </div>\n    </div>\n</template>\n\n<script>\nimport { mapState } from \"vuex\";\nimport { isNullOrUndefined } from \"../../helper/utils\";\n\nimport LiveShoppingDetails from \"./LiveShoppingDetails.vue\";\nimport ItemStoreSpecial from \"../itemList/ItemStoreSpecial.vue\";\n\nconst TimeEnum = Object.freeze({ past: 1, now: 2, future: 3 });\n\nexport default {\n\n    components:\n    {\n        LiveShoppingDetails,\n        ItemStoreSpecial\n    },\n\n    props: {\n        liveShoppingId:\n        {\n            type: Number,\n            required: true,\n            validator: value =>\n            {\n                return value % 1 === 0 && value >= 1 && value <= 10;\n            }\n        },\n        displaySettings:\n        {\n            type: Object\n        },\n        paddingClasses:\n        {\n            type: String,\n            default: null\n        },\n        paddingInlineStyles:\n        {\n            type: String,\n            default: null\n        },\n        sorting:\n        {\n            type: String,\n            default: null\n        },\n        showNetPrices:\n        {\n            type: Boolean\n        }\n    },\n\n    computed:\n    {\n        currentOffer()\n        {\n            return this.$store.state.liveShopping.liveShoppingOffers[this._uid];\n        },\n\n        isActive()\n        {\n            return this.isActiveByTime && this.isActiveByStock;\n        },\n\n        isActiveByTime()\n        {\n            if (!isNullOrUndefined(this.currentOffer))\n            {\n                const begin = parseInt(this.currentOffer.liveShopping.fromTime) * 1000;\n                const end = parseInt(this.currentOffer.liveShopping.toTime) * 1000;\n                const now = Date.now();\n\n                return begin < now && now < end;\n            }\n\n            return false;\n        },\n\n        isActiveByStock()\n        {\n            if (!isNullOrUndefined(this.currentOffer))\n            {\n                const liveShopping = this.currentOffer.liveShopping;\n\n                return liveShopping.quantitySold < liveShopping.quantityMax;\n            }\n\n            return false;\n        },\n\n        storeSpecial()\n        {\n            if (!isNullOrUndefined(this.currentOffer))\n            {\n                if (this.isActive)\n                {\n                    return { id: 1 };\n                }\n\n                const offerTime = this.whenIsCurrentOffer();\n                let name = \"\";\n\n                if (offerTime === TimeEnum.past)\n                {\n                    name = this.$translate(\"Ceres::Template.liveShoppingOfferClosed\");\n                }\n                else if (offerTime === TimeEnum.future)\n                {\n                    name = this.$translate(\"Ceres::Template.liveShoppingNextOffer\");\n                }\n                else if (offerTime === TimeEnum.now)\n                {\n                    name = this.$translate(\"Ceres::Template.liveShoppingOfferSoldOut\");\n                }\n\n                return { id: -1, names: { name } };\n            }\n\n            return null;\n        },\n\n        prices()\n        {\n            const itemPrices = this.currentOffer.item.prices;\n            const prices = {\n                price: itemPrices.default,\n                rrp: itemPrices.rrp,\n                isRrpDefaultPrice: false\n            };\n\n            if (!isNullOrUndefined(itemPrices.specialOffer))\n            {\n                prices.price = itemPrices.specialOffer;\n                prices.rrp = itemPrices.default || itemPrices.rrp;\n                prices.isRrpDefaultPrice = !!itemPrices.default;\n            }\n\n            return prices;\n        }\n    },\n\n    mounted()\n    {\n        this.reloadOffer();\n    },\n\n    methods:\n    {\n        whenIsCurrentOffer()\n        {\n            const begin = parseInt(this.currentOffer.liveShopping.fromTime) * 1000;\n            const end = parseInt(this.currentOffer.liveShopping.toTime) * 1000;\n            const now = Date.now();\n\n            if (begin < now && now > end)\n            {\n                return TimeEnum.past;\n            }\n\n            if (begin < now && now < end)\n            {\n                return TimeEnum.now;\n            }\n\n            return TimeEnum.future;\n        },\n\n        reloadOffer()\n        {\n            this.$store.dispatch(\"retrieveLiveShoppingOffer\", { liveShoppingId: this.liveShoppingId, sorting: this.sorting, uid: this._uid });\n        }\n    }\n}\n</script>\n","import mod from \"-!../../../../../../node_modules/babel-loader/lib/index.js!../../../../../../node_modules/vue-loader/lib/index.js??vue-loader-options!./LiveShoppingItem.vue?vue&type=script&lang=js&\"; export default mod; export * from \"-!../../../../../../node_modules/babel-loader/lib/index.js!../../../../../../node_modules/vue-loader/lib/index.js??vue-loader-options!./LiveShoppingItem.vue?vue&type=script&lang=js&\"","import { render, staticRenderFns } from \"./LiveShoppingItem.vue?vue&type=template&id=3c96f6c0&\"\nimport script from \"./LiveShoppingItem.vue?vue&type=script&lang=js&\"\nexport * from \"./LiveShoppingItem.vue?vue&type=script&lang=js&\"\n\n\n/* normalize component */\nimport normalizer from \"!../../../../../../node_modules/vue-loader/lib/runtime/compo